# Re-enable NTFS Last Access Timestamp Write-Host "Re-enabling NTFS last access timestamp updates..." -ForegroundColor Cyan # Set NtfsDisableLastAccessUpdate to 0 (enabled) Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem" -Name "NtfsDisableLastAccessUpdate" -Value 0x80000000 -Type DWord -Force -ErrorAction Stop Write-Host "NTFS last access timestamp updates have been re-enabled." -ForegroundColor Green